<?php
require_once 'functions.php';require_role(['pelanggan']);$uid=(int)user()['id_user'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id_produk'];$pdo->prepare("DELETE FROM tbl_favorit WHERE id_user=? AND id_produk=?")->execute([$uid,$id]);flash('Produk dihapus dari favorit.');go('favorit.php');}$s=$pdo->prepare("SELECT p.* FROM tbl_favorit f JOIN tbl_produk p ON p.id_produk=f.id_produk WHERE f.id_user=?");$s->execute([$uid]);$rows=$s->fetchAll();layout_header('Favorit');?><div class="page-title"><div><span class="eyebrow">SIMPANAN PRODUK</span><h1>Produk favorit</h1></div></div><div class="product-grid"><?php foreach($rows as $p):?><article class="product-card"><a class="product-photo" href="detail_produk.php?id=<?=$p['id_produk']?>"><img src="<?=e(product_image($p['foto']))?>"></a><div class="product-info"><h3><?=e($p['nama_produk'])?></h3><strong><?=rupiah($p['harga'])?></strong><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id_produk" value="<?=$p['id_produk']?>"><button class="btn btn-danger full">Hapus Favorit</button></form></div></article><?php endforeach;?></div><?php layout_footer(); ?>